import { PASSWORD, USERS, expect, test } from "../../fixtures";

test("unknown email is rejected the same way as a wrong password", { tag: "@AUTH-03" }, async ({ request }) => {
  // Act
  const response = await request.post("/api/auth/login", {
    data: { email: "nobody@northwind.test", password: "demo-password" },
  });

  // Assert
  const text = await response.text();
  expect(response.status(), text).toBe(401);
  const body = JSON.parse(text);
  expect(body.error?.code, text).toBe("invalid_credentials");

  // Same rejection as a wrong password for a known user
  const wrong = await request.post("/api/auth/login", {
    data: { email: USERS.member, password: PASSWORD + "-wrong" },
  });
  const wrongText = await wrong.text();
  expect(wrong.status(), wrongText).toBe(401);
  expect(JSON.parse(wrongText).error?.code, wrongText).toBe(body.error?.code);
});
